SELECT DATE_TRUNC('MONTH', starts_on) AS activity_month, CASE WHEN discount_pct >= 0.36 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN channel = 'mobile' THEN 1 END), 0), 2) AS discount_pct_per_mobile, COUNT(DISTINCT channel) AS distinct_channels FROM promotions GROUP BY DATE_TRUNC('MONTH', starts_on), CASE WHEN discount_pct >= 0.36 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING distinct_channels < 1;
